const v1 = '{"storageVersion":1,"trips":[{"id":"t9","name":"Old","members":[{"id":"a","name":"Ana"}],"expenses":[{"id":"x","title":"Lunch","amountCents":1000,"paidBy":"a","date":"2026-01-01T00:00:00.000"}]}]}';

void main() {
  test('data saved by version 1 still loads, with EUR', () {
    final trips = JsonTripStorage().decode(v1);
    expect(trips.single.expenses.single.title, 'Lunch');
    expect(trips.single.expenses.single.currency, 'EUR');
  });
  test('new data is saved as version 2 and keeps the currency', () {
    final trip = Trip(
      id: 't1',
      name: 'US',
      members: const [Member('a', 'Ana')],
      expenses: [Expense(id: 'e', title: 'Taxi', amountCents: 500, paidBy: 'a', date: DateTime(2026, 1, 2), currency: 'USD')],
    );
    final text = JsonTripStorage().encode([trip]);
    expect((jsonDecode(text) as Map)['storageVersion'], 2);
    expect(JsonTripStorage().decode(text).single.expenses.single.currency, 'USD');
  });
  test('an unknown future version is refused', () {
    expect(() => JsonTripStorage().decode('{"storageVersion":99,"trips":[]}'), throwsFormatException);
  });
  test('an expense without a given currency is EUR', () {
    expect(Expense(id: 'e', title: 'T', amountCents: 1, paidBy: 'a', date: DateTime(2026)).currency, 'EUR');
  });
}

