void main() {
  test('splitEvenly hands the extra cents to the first people', () {
    expect(splitEvenly(1000, 3), [334, 333, 333]);
    expect(splitEvenly(900, 3), [300, 300, 300]);
    expect(splitEvenly(1, 3), [1, 0, 0]);
    expect(splitEvenly(0, 4), [0, 0, 0, 0]);
  });
  test('balances always add up to zero', () {
    final trip = Trip(
      id: 'x',
      name: 'Odd',
      members: const [Member('a', 'A'), Member('b', 'B'), Member('c', 'C')],
      expenses: [Expense(id: 'e', title: 'T', amountCents: 1000, paidBy: 'a', date: DateTime(2026))],
    );
    final net = netBalances(trip);
    expect(net.values.fold<int>(0, (a, b) => a + b), 0);
    expect(net['a'], 666);
    expect(net['b'], -333);
    expect(net['c'], -333);
  });
}

