class _NoTrips extends TripsController {
  @override
  List<Trip> build() => const [];
}

void main() {
  testWidgets('empty state: big icon, friendly text, a real button that opens the dialog', (tester) async {
    tester.view.physicalSize = const Size(320, 480);
    tester.view.devicePixelRatio = 1;
    tester.platformDispatcher.textScaleFactorTestValue = 1.5;
    addTearDown(() {
      tester.view.resetPhysicalSize();
      tester.view.resetDevicePixelRatio();
      tester.platformDispatcher.clearTextScaleFactorTestValue();
    });
    await pumpApp(tester, '/', overrides: [tripsProvider.overrideWith(_NoTrips.new)]);
    expect(tester.takeException(), isNull, reason: 'no overflow on a small phone with large text');
    final label = find.text('Create your first trip');
    expect(label, findsOneWidget);
    final button = find.ancestor(of: label, matching: find.byWidgetPredicate((w) => w is ButtonStyleButton));
    expect(button, findsOneWidget, reason: 'a real button');
    final rect = tester.getRect(button);
    expect(rect.height, greaterThanOrEqualTo(48), reason: 'comfortable tap target');
    expect(rect.left, greaterThanOrEqualTo(0));
    expect(rect.right, lessThanOrEqualTo(320));
    final reachable = rect.bottom <= 480 || find.ancestor(of: button, matching: find.byType(Scrollable)).evaluate().isNotEmpty;
    expect(reachable, isTrue, reason: 'the button is visible, or the content scrolls so it can be reached');
    expect(find.byWidgetPredicate((w) => w is Icon && (w.size ?? 0) >= 48), findsWidgets, reason: 'a large icon');
    await tester.ensureVisible(button);
    await tester.pumpAndSettle();
    await tester.tap(button);
    await tester.pumpAndSettle();
    expect(find.byType(AlertDialog), findsOneWidget);
    expect(find.byType(TextField), findsOneWidget);
  });
}

