Future<void> pumpApp(WidgetTester tester, String path, {List<Override> overrides = const []}) async {
  appRouter.go(path);
  await tester.pumpWidget(ProviderScope(overrides: overrides, child: const App()));
  await tester.pumpAndSettle();
}

void main() {
  testWidgets('settle up flow', (tester) async {
    tester.view.physicalSize = const Size(320, 640);
    tester.view.devicePixelRatio = 1;
    addTearDown(() {
      tester.view.resetPhysicalSize();
      tester.view.resetDevicePixelRatio();
    });
    await pumpApp(tester, '/trip/t1/balances');
    expect(tester.takeException(), isNull);
    expect(find.text('Ben pays Ana'), findsOneWidget);
    expect(find.text('Cleo pays Ana'), findsOneWidget);
    expect(find.text('Mark as paid'), findsNWidgets(2));
    await tester.tap(find.text('Mark as paid').first);
    await tester.pumpAndSettle();
    expect(find.text('Ben pays Ana'), findsNothing);
    expect(find.text('Cleo pays Ana'), findsOneWidget);
    expect(find.text('Mark as paid'), findsOneWidget);
    // Leave the screen and come back: still paid.
    appRouter.go('/');
    await tester.pumpAndSettle();
    appRouter.go('/trip/t1/balances');
    await tester.pumpAndSettle();
    expect(find.text('Ben pays Ana'), findsNothing);
    expect(find.text('Cleo pays Ana'), findsOneWidget);
    await tester.tap(find.text('Mark as paid'));
    await tester.pumpAndSettle();
    expect(find.text('All settled.'), findsOneWidget);
    expect(tester.takeException(), isNull);
  });
}

