String firstTitle(WidgetTester tester) {
  final tile = tester.widgetList<ListTile>(find.byType(ListTile)).first;
  return (tile.title as Text).data!;
}

void main() {
  testWidgets('favorites go first and the star works on both screens', (tester) async {
    await pumpApp(tester, '/');
    expect(firstTitle(tester), 'Lisbon');
    expect(find.byTooltip('Favorite'), findsNWidgets(2));
    await tester.tap(find.byTooltip('Favorite').at(1));
    await tester.pumpAndSettle();
    expect(firstTitle(tester), 'Berlin');
    expect(find.byTooltip('Unfavorite'), findsOneWidget);
    await pumpApp(tester, '/trip/t2');
    expect(find.byTooltip('Unfavorite'), findsOneWidget);
    await tester.tap(find.byTooltip('Unfavorite'));
    await tester.pumpAndSettle();
    expect(find.byTooltip('Favorite'), findsOneWidget);
    appRouter.go('/');
    await tester.pumpAndSettle();
    expect(firstTitle(tester), 'Lisbon');
  });
}

